104	  // ── 캐릭터 능력 시스템 ────────────────────────────────────────────────
105	  protected ability!: CharacterAbility;
106	  protected abilityAPI!: GameSceneAPI;
107	  // [디버그] 수동 충돌 영역 시각화
108	  private manualHitboxDebug?: Phaser.GameObjects.Graphics;
109	
110	  constructor(key: string = 'GameScene') {
111	    super(key);
112	  }
113	
114	  init(data: { gameMode?: GameMode; difficulty?: Difficulty; purePhysical?: boolean }) {
115	    // 게임 재시작 시 점수 관련 변수 초기화
116	    this.score = 0;
117	    this.gameOver = false;
118	    this.difficultyLevel = 2;
119	    this.lastGoldPoopScore = 0;
120	    this.lastDiamondPoopScore = 0;
121	    this.lastTopazPoopScore = 0;
122	    this.gameStartTime = realNow();
123	    this.phaserStartTime = 0; // create()에서 설정
124	    this.lastScoreTime = realNow();
125	    this.goldCollected = 0;
126	    this.cheatSuspicionCount = 0;
127	    this.diamondCollected = 0;
128	    this.topazCollected = 0;
129	    this.rainbowCollected = 0;
130	    this.collectBonusTotal = 0;
131	    this.abilityBonusTotal = 0;
132	    this.sessionPromise = null; // 재시작 시 이전 세션 프로미스 해제
133	    // 디버그 Graphics 참조 초기화 (씬 재시작 시 이전 객체는 Phaser가 파괴하므로 참조만 해제)
134	    this.manualHitboxDebug = undefined;
135	    // 피버 타임 초기화
136	    this.isFeverTime = false;
137	    this.feverTimeRemaining = 0;
138	    this.lastFeverTimeScore = 0;
139	    this.feverCount = 0;
140	    this.isRainbowFever = false;
141	    this.lastClearPoopsScore = 0;
142	    // 캐릭터 선택 화면에서 저장한 캐릭터 & 배경화면 사용
143	    this.selectedCharId = getSafeSelectedCharacter();
144	    this.selectedWpId = getSafeSelectedWallpaper();
145	    const charDef        = getCharacterDef(this.selectedCharId);
146	    const dupCount       = getDuplicateCount(this.selectedCharId);
147	    const awakeLevel     = getAwakeningLevel(charDef.grade, dupCount);
148	    this.selectedCharGrade = charDef.grade;
149	    this.charAwakeLevel    = awakeLevel;
150	    this.purePhysical = data.purePhysical ?? false;
151	    this.ability = getCharacterAbility(this.selectedCharId, awakeLevel);
152	    if (this.purePhysical) this.ability = new BaseAbility();
153	    this.activeSynergy = this.purePhysical ? null : getSynergy(this.selectedWpId, this.selectedCharId);
154	
155	    // ModeSelectScene/DifficultySelectScene으로부터 게임 모드와 난이도를 받음
156	    if (data.gameMode) {
157	      this.gameMode = data.gameMode;
158	      // console.log('Game Mode:', this.gameMode);
159	    }
160	    if (data.difficulty) {
161	      this.difficulty = data.difficulty;
162	      localStorage.setItem('lastPlayedDifficulty', this.scoreDifficulty);
163	    }
164	
165	    // 난이도 설정 찾기
166	    const config = DIFFICULTIES.find(d => d.difficulty === this.difficulty);
167	    if (config) {
168	      this.difficultyConfig = config;
169	    } else {
170	      // 기본값은 HARD
171	      this.difficultyConfig = DIFFICULTIES.find(d => d.difficulty === Difficulty.HARD)!;
172	    }
173	  }
174	
175	  preload() {
176	    // 선택된 배경화면 조건부 로딩 (DifficultySelectScene에서 미리 로드 안 된 경우 fallback)
177	    const wpDef = this.selectedWpId ? getWallpaperDef(this.selectedWpId) : null;
178	    if (wpDef && !this.textures.exists(wpDef.bgKey)) {
179	      this.load.image(wpDef.bgKey, wpDef.bgPath);
180	    }
181	
182	    // DifficultySelectScene에서 미리 로딩됨. 캐시에 없을 경우에만 fallback 로딩.
183	
184	    if (this.difficulty === Difficulty.NORMAL && !this.textures.exists('background3')) {
185	      this.load.image('background3', 'assets/backgrounds/background3.webp');
186	    } else if (this.difficulty === Difficulty.HARD && !this.textures.exists('background')) {
187	      this.load.image('background', 'assets/backgrounds/background.webp');
188	    } else if (this.difficulty === Difficulty.EXTREME && !this.textures.exists('background2')) {
189	      this.load.image('background2', 'assets/backgrounds/background2.webp');
190	    }
191	    if (this.difficulty === Difficulty.EXTREME && isChristmasSeason() && !this.textures.exists('xmas_background')) {
192	      this.load.image('xmas_background', 'assets/backgrounds/xmas_background.webp');
193	    }
194	
195	    // Player assets
196	    const CHARS_WITH_SPRITES = GameScene.CHARS_WITH_SPRITES;
197	    if (CHARS_WITH_SPRITES.includes(this.selectedCharId)) {
198	      const p = `${this.selectedCharId}_`;
199	      if (!this.textures.exists(`${p}front`)) this.load.image(`${p}front`, `assets/players/${p}front.webp`);
200	      if (!this.textures.exists(`${p}left`)) this.load.image(`${p}left`, `assets/players/${p}left.webp`);
201	      if (!this.textures.exists(`${p}right`)) this.load.image(`${p}right`, `assets/players/${p}right.webp`);
202	      if (this.selectedCharId === 'mugi') {
203	        if (!this.textures.exists('gold_mugi_front')) this.load.image('gold_mugi_front', 'assets/players/gold_mugi_front.webp');
204	        if (!this.textures.exists('gold_mugi_left'))  this.load.image('gold_mugi_left',  'assets/players/gold_mugi_left.webp');
205	        if (!this.textures.exists('gold_mugi_right')) this.load.image('gold_mugi_right', 'assets/players/gold_mugi_right.webp');
206	      }
207	    } else {
208	      // chibi (기본) 또는 플레이어 스프라이트가 없는 UR 캐릭터 → 치비로 fallback
209	      if (!this.textures.exists('front')) this.load.image('front', 'assets/players/chibi_front.webp');
210	      if (!this.textures.exists('left')) this.load.image('left', 'assets/players/chibi_left.webp');
211	      if (!this.textures.exists('right')) this.load.image('right', 'assets/players/chibi_right.webp');
212	    }
213	
214	    if (!this.textures.exists('poop')) this.load.image('poop', 'assets/poops/poop.webp');
215	    if (!this.textures.exists('poop_glasses')) this.load.image('poop_glasses', 'assets/poops/poop_glasses.webp');
216	    if (!this.textures.exists('poop_sunglass')) this.load.image('poop_sunglass', 'assets/poops/poop_sunglass.webp');
217	    if (!this.textures.exists('poop_sunglass2')) this.load.image('poop_sunglass2', 'assets/poops/poop_sunglass2.webp');
218	    if (!this.textures.exists('poop_smile')) this.load.image('poop_smile', 'assets/poops/poop_smile.webp');
219	    if (!this.textures.exists('gold_poop')) this.load.image('gold_poop', 'assets/poops/gold_poop.webp');
220	    if (!this.textures.exists('diamond_poop')) this.load.image('diamond_poop', 'assets/poops/diamond_poop.webp');
221	    if (!this.textures.exists('topaz_poop')) this.load.image('topaz_poop', 'assets/poops/topaz.webp');
222	    if (!this.textures.exists('rainbow_poop')) this.load.image('rainbow_poop', 'assets/poops/rainbow_poop.webp');
223	
224	    if (this.difficulty === Difficulty.EXTREME && isChristmasSeason()) {
225	      if (!this.textures.exists('xmas_poop_ribbon')) this.load.image('xmas_poop_ribbon', 'assets/poops/xmas_present_poop.webp');
226	      if (!this.textures.exists('xmas_poop_nose')) this.load.image('xmas_poop_nose', 'assets/poops/xmas_nose_poop.webp');
227	      if (!this.textures.exists('xmas_poop_santa')) this.load.image('xmas_poop_santa', 'assets/poops/xmas_santa_poop.webp');
228	      if (!this.textures.exists('xmas_poop_rudolf')) this.load.image('xmas_poop_rudolf', 'assets/poops/xmas_rudolf_poop.webp');
229	      if (!this.textures.exists('xmas_poop_beard')) this.load.image('xmas_poop_beard', 'assets/poops/xmas_beard_poop.webp');
230	    }
231	
232	    // BGM
233	    if (this.difficulty === Difficulty.EXTREME && isChristmasSeason()) {
234	      if (!this.cache.audio.exists('xmasBgMusic')) this.load.audio('xmasBgMusic', 'assets/bgms/xmas_poop.mp3');
235	    } else {
236	      if (!this.cache.audio.exists('bgMusic')) this.load.audio('bgMusic', 'assets/bgms/poop.mp3');
237	    }
238	  }
239	
240	  private getDefaultBackgroundKey(): string {
241	    if (this.difficulty === Difficulty.NORMAL) return 'background3';
242	    if (this.difficulty === Difficulty.EXTREME) {
243	      return isChristmasSeason() ? 'xmas_background' : 'background2';
244	    }
245	    return 'background'; // EASY / HARD
246	  }
247	
248	  create() {
249	    super.create();
250	
251	    // 키보드 이벤트 수신을 위해 캔버스 포커스 설정
252	    const canvas = this.game.canvas;
253	    canvas.setAttribute('tabindex', '0');
254	    canvas.focus();
255	
256	    // Phaser 내부 시간 기준점 기록 (씬 재시작 시에도 정확한 delta 계산)
257	    this.phaserStartTime = this.time.now;
258	    // rAF 체크 두 기준점을 동시에 설정 — preload 시간 불일치 방지
259	    this.resetCheatCheckpoints();
260	
261	    // 난이도별 최고 점수 로드
262	    this.highScore = getHighScore(this.scoreDifficulty);
263	
264	    // 배경 이미지: 선택된 배경화면 우선, 없으면 난이도별 기본
265	    const wpDefForBg = this.selectedWpId ? getWallpaperDef(this.selectedWpId) : null;
266	    const backgroundKey = (wpDefForBg && this.textures.exists(wpDefForBg.bgKey))
267	      ? wpDefForBg.bgKey
268	      : this.getDefaultBackgroundKey();
269	
270	    const W = this.scale.width;
271	    const H = this.scale.height;
272	    const cx = W / 2;
273	
274	    const background = this.add.image(cx, H / 2, backgroundKey);
275	    background.setDisplaySize(W, H);
276	
277	    // BGM 키 결정 (preload에서 이미 로드됨)
278	    let bgMusicKey = 'bgMusic';
279	    if (this.difficulty === Difficulty.EXTREME && isChristmasSeason()) {
280	      bgMusicKey = 'xmasBgMusic';
281	    }
282	
283	    // 이전 bgMusic 인스턴스가 있으면 전역 SoundManager에서 제거
284	    if (this.bgMusic) {
285	      this.bgMusic.destroy();
286	    }
287	
288	    // BGM 재생 (preload에서 이미 로드 완료됨)
289	    this.bgMusic = this.sound.add(bgMusicKey, { loop: true, volume: 0.5 });
290	    this.bgMusic.play();
291	
292	    // 월드 바운드 설정 (플레이어가 화면 안쪽에만 머무르도록)
293	    this.physics.world.setBounds(15, 0, W - 30, H);
294	
295	    // 플레이어 생성 (난이도별 속도 적용, 게임 모드별 스프라이트)
296	    const CHARS_WITH_SPRITES = GameScene.CHARS_WITH_SPRITES;
297	    let playerTexturePrefix = '';
298	    if (CHARS_WITH_SPRITES.includes(this.selectedCharId)) {
299	      playerTexturePrefix = `${this.selectedCharId}_`;
300	    }
301	    // 등급 각성 패시브: ★1 R+5/SR+10/UR+15, ★2 R+10/SR+15/UR+20
302	    // 매화 예외: ★1 +5, ★2+ 속도 패시브 없음 (대신 특수똥 수집 +5pt)
303	    const _gs = (r: number, sr: number, ur: number) =>
304	      this.selectedCharGrade === 'UR' ? ur
305	      : this.selectedCharGrade === 'SR' ? sr
306	      : this.selectedCharGrade === 'R'  ? r
307	      : 0;
308	    const gradeAwakeSpeed = this.selectedCharId === 'maehwa'
309	      ? (this.charAwakeLevel >= 1 ? 5 : 0)
310	      : this.charAwakeLevel >= 2 ? _gs(10, 15, 20)
311	      : this.charAwakeLevel >= 1 ? _gs(5, 10, 15)
312	      : 0;
313	    const [playerW, playerH] = getCharacterDef(this.selectedCharId).playerDisplaySize ?? [50, 80];
314	    this.player = new Player(this, cx, H - 80, this.difficultyConfig.playerSpeed + this.ability.getPlayerSpeedBonus() + gradeAwakeSpeed + (this.activeSynergy?.speedBonus ?? 0), playerTexturePrefix, playerW, playerH);
315	
316	    // 💩 그룹 생성 (Object Pool: maxSize로 상한 설정)
317	    this.poops = this.physics.add.group({
318	      classType: Poop,
319	      runChildUpdate: true,
320	      maxSize: 60,
321	    });
322	
323	    // 금똥 그룹 생성
324	    this.goldPoops = this.physics.add.group({
325	      classType: GoldPoop,
326	      runChildUpdate: true,
327	      maxSize: 20,
328	    });
329	
330	    // 다이아똥 그룹 생성
331	    this.diamondPoops = this.physics.add.group({
332	      classType: DiamondPoop,
333	      runChildUpdate: true,
334	      maxSize: 20,
335	    });
336	
337	    // 토파즈똥 그룹 생성
338	    this.topazPoops = this.physics.add.group({
339	      classType: TopazPoop,
340	      runChildUpdate: true,
341	      maxSize: 10,
342	    });
343	
344	    // 무지개똥 그룹 생성 (레인보우 피버 시 최대 30개 동시 활성 가능)
345	    this.rainbowPoops = this.physics.add.group({
346	      classType: RainbowPoop,
347	      runChildUpdate: true,
348	      maxSize: 30,
349	    });
350	
351	    // 풀 사전 할당 — create() 시점에 오브젝트를 미리 생성해 게임 중 런타임 생성 히치 방지
352	    const prewarm = (group: Phaser.Physics.Arcade.Group, count: number) => {
353	      for (let i = 0; i < count; i++) {
354	        const obj = group.get(0, -200) as Phaser.Physics.Arcade.Sprite;
355	        if (obj) {
356	          obj.setActive(false).setVisible(false);
357	          const body = obj.body as Phaser.Physics.Arcade.Body;
358	          if (body) body.setEnable(false);
359	        }
360	      }
361	    };
362	    prewarm(this.poops, 36);        // 스폰당 최대 6개 × 여유
363	    prewarm(this.goldPoops, 5);
364	    prewarm(this.diamondPoops, 5);
365	    prewarm(this.topazPoops, 4);
366	    prewarm(this.rainbowPoops, 4);
367	
368	    // 충돌 감지
369	    this.physics.add.overlap(
370	      this.player,
371	      this.poops,
372	      this.hitPoop as Phaser.Types.Physics.Arcade.ArcadePhysicsCallback,
373	      undefined,
374	      this
375	    );
376	
377	    // 금똥 충돌 감지 (수집)
378	    this.physics.add.overlap(
379	      this.player,
380	      this.goldPoops,
381	      this.collectGoldPoop as Phaser.Types.Physics.Arcade.ArcadePhysicsCallback,
382	      undefined,
383	      this
384	    );
385	
386	    // 다이아똥 충돌 감지 (수집)
387	    this.physics.add.overlap(
388	      this.player,
389	      this.diamondPoops,
390	      this.collectDiamondPoop as Phaser.Types.Physics.Arcade.ArcadePhysicsCallback,
391	      undefined,
392	      this
393	    );
394	
395	    // 토파즈똥 충돌 감지 (수집)
396	    this.physics.add.overlap(
397	      this.player,
398	      this.topazPoops,
399	      this.collectTopazPoop as Phaser.Types.Physics.Arcade.ArcadePhysicsCallback,
400	      undefined,

